foreach(int mode in new[]{0,1,2})foreach(int reason in new[]{0,1,2,3,4,5}){Reset();var boss=CloudParent();var child=CloudChild(boss);Main.netMode=mode;if(reason==0)boss.NPC.active=false;else if(reason==1)Main.player[0].dead=true;else if(reason==2)boss.NPC.target=255;else if(reason==3)child.NPC.Center=new(4001,0);else if(reason==4)child.NPC.velocity=new(float.NaN,0);else{Main.netMode=0;CloudParent();Main.netMode=mode;}int cooldown=0;Check(!child.CanHitPlayer(Main.player[0],ref cooldown),"invalid cloud source contact blocked");Check(!child.PreAI()&&child.NPC.velocity==Microsoft.Xna.Framework.Vector2.Zero,"invalid cloud source freezes");Check(child.NPC.active==(mode==1),"only authority clears cloud summons");Check(NetMessage.Calls==(mode==2?1:0),"cloud cleanup dedicated broadcast");}
Reset();var cloudOwner=CloudParent();var cloudChild=CloudChild(cloudOwner);for(int tick=0;tick<899;tick++)Check(cloudChild.PreAI(),"cloud summon lives before nine hundred ticks");Check(!cloudChild.PreAI()&&!cloudChild.NPC.active&&cloudChild.NPC.damage==0,"cloud expires without death rewards");Reset();cloudOwner=CloudParent();cloudChild=CloudChild(cloudOwner);var cloudWire=Save(cloudChild);Check(cloudWire.Length==13&&Save(cloudOwner).Length==8,"cloud source fixed wire layouts");for(int length=0;length<13;length++){try{Read(cloudChild,cloudWire[..length]);throw new Exception("truncated cloud source accepted");}catch(EndOfStreamException){}Check(Save(cloudChild).SequenceEqual(cloudWire),"cloud truncated source read atomic");}Main.netMode=1;for(int tick=0;tick<1000;tick++)cloudChild.PreAI();Check(Save(cloudChild).SequenceEqual(cloudWire),"cloud client never ages summon");Reset();var naturalCloud=new TribulationCloudling();naturalCloud.OnSpawn(new NaturalSource());Check(naturalCloud.PreAI(),"natural archived soul lifecycle unchanged");

foreach(int mode in new[]{0,1,2}) {
 Reset();Main.player[1].active=true;var boss=CloudParent();var child=CloudChild(boss);boss.NPC.target=1;Main.netMode=mode;int cooldown=0;
 Check(!child.CanHitPlayer(Main.player[0],ref cooldown)&&!child.CanHitNPC(new()),"Cloud target mismatch blocks contact before AI");var before=Save(child);
 Check(child.PreAI()==(mode!=1)&&child.NPC.active,"Cloud target mismatch waits on client and aligns on authority");
 if(mode==1){Check(Save(child).SequenceEqual(before),"Waiting cloud client never ages summon");child.NPC.target=1;}else Check(child.NPC.target==1&&child.NPC.netUpdate,"Authority synchronizes cloud follower target");
 Check(child.PreAI()&&child.CanHitPlayer(Main.player[1],ref cooldown),"Cloud matching target resumes normal AI and contact");
}
