var remoteCloud=new TribulationCloudAvatar{NPC=orderedCloud.NPC};remoteCloud.NPC.ModNPC=remoteCloud;var remoteCloudChild=new TribulationCloudling{NPC=new(){active=true,life=70}};Read(remoteCloudChild,childPacket);int cloudCooldown=0;
Check(!remoteCloudChild.PreAI()&&!remoteCloudChild.CanHitPlayer(Main.player[0],ref cloudCooldown)&&remoteCloudChild.NPC.active,"Cloud child packet before parent waits harmlessly");Read(remoteCloud,parentPacket);Check(remoteCloudChild.PreAI()&&remoteCloudChild.CanHitPlayer(Main.player[0],ref cloudCooldown),"Late cloud parent session restores client prediction");
for(int length=0;length<8;length++){var before=Save(remoteCloud);try{Read(remoteCloud,parentPacket[..length]);throw new Exception("truncated cloud parent accepted");}catch(EndOfStreamException){}Check(Save(remoteCloud).SequenceEqual(before),"Cloud parent truncated packet atomic");}
